}

function renderOverview(){
 const n=$('qmOverview');if(!state){n.innerHTML='<div class="qm-empty"><strong>Start with a business</strong>Choose the business whose catalog and documents you want to work on.</div>';return;}
 const active=state.catalog.filter(x=>x.active),drafts=state.documents.filter(x=>x.status==='draft'),finalized=state.documents.filter(x=>x.status==='finalized'),houseHull=isHouseHull(),recent=[...state.documents].reverse().slice(0,3);
 const icon=body=>`<svg class="qm-ui-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${body}</svg>`,arrow=icon('<path d="M5 12h14m-5-5 5 5-5 5"/>'),paper=icon('<path d="M14 3H6a2 2 0 0 0-2 2v15h16V9l-6-6Zm0 0v6h6M8 13h8M8 17h5"/>');
 const artwork=houseHull?`<svg class="qm-house-elevation" viewBox="0 0 360 210" aria-hidden="true" focusable="false"><g class="qm-art-guides"><path d="M24 18v12m-6-6h12M46 184v18m285-18v18M46 195h285m-290 5 10-10m275 10 10-10M349 106v70m-5-75 10 10m-10 60 10 10M338 106h19M338 176h19"/><path d="M46 184V99M331 184v-72" stroke-dasharray="3 5"/></g><g class="qm-art-structure"><path d="M18 176h324M46 99l113-71 114 71M38 99l121-78 122 78M61 94v82h196V94M219 60V32h20v41M215 32h28M257 176h74v-66l-77-26M267 89l72 21h-82"/><path d="M64 104h190M64 115h24m37 0h19m34 0h16m37 0h23M64 126h24m37 0h19m34 0h16m37 0h23M64 137h24m37 0h19m34 0h16m37 0h23M64 148h80m34 0h76M64 159h80m34 0h76M64 170h80m34 0h76M261 120h66M261 132h10m50 0h6M261 144h10m50 0h6M261 156h10m50 0h6M261 168h10m50 0h6" class="qm-art-siding"/><path d="M88 109h37v34H88zM93 114h27v24H93zM106.5 114v24M93 126h27M194 109h37v34h-37zM199 114h27v24h-27zM212.5 114v24M199 126h27M144 115h34v61h-34zM150 121h22v32h-22zM150 158h22v12h-22zM146 66h27v27h-27zM150 70h19v19h-19zM159.5 70v19M150 79.5h19M271 126h50v50h-50zM275 132h42M275 140h42M275 148h42M275 156h42M275 164h42M137 176v5h48v-5"/><path d="M184 158h2M41 176v-18m0 9c-12-2-16-10-10-15 8-5 11 5 10 15Zm0-4c1-13 9-19 14-12 5 7-4 13-14 12Z"/></g></svg>`:`<svg class="qm-document-art" viewBox="0 0 360 210" aria-hidden="true" focusable="false"><g class="qm-art-guides"><path d="M66 35h20m-10-10v20M274 163h20m-10-10v20M62 191h235"/><circle cx="192" cy="103" r="82" stroke-dasharray="3 7"/></g><g class="qm-art-structure"><path d="M129 40h111l22 22v119H129z"/><path d="M97 25h101l29 29v117H97z" fill="#f4f3e9"/><path d="M198 25v29h29M115 79h94M115 96h94M115 113h94M115 130h94M115 147h45M115 49h48M115 60h31M179 79v51"/></g></svg>`;
 n.innerHTML=`<div class="qm-studio-hero ${houseHull?'qm-househull-hero':'qm-business-hero'}"><div class="qm-hero-copy"><span class="qm-studio-eyebrow">${houseHull?'EXTERIOR PROJECT WORKSPACE':'YOUR BUSINESS WORKSPACE'}</span><h2 title="${esc(state.business.name||selectedBusiness()?.name)}">${esc(state.business.name||selectedBusiness()?.name)}</h2><p>${houseHull?'Good work starts with a clear quote.':'Your products, services and customer documents.'}</p><div class="qm-actions"><button id="qmNewQuote" class="qm-primary" type="button">${icon('<path d="M12 5v14M5 12h14"/>')}<span>New quote</span></button><button id="qmNewInvoice" type="button">New invoice</button></div></div><div class="qm-hero-art">${artwork}</div><div class="qm-studio-metrics"><div><strong>${active.length}</strong><span>Active parts<br> &amp; services</span></div><div><strong>${drafts.length}</strong><span>Saved drafts</span></div><div><strong>${finalized.length}</strong><span>Finalized copies</span></div></div></div><div class="qm-overview-workgrid"><section class="qm-recent"><div class="qm-recent-head"><h3>Recent documents</h3><span>${state.documents.length} saved</span></div>${recent.length?`<div class="qm-recent-list">${recent.map(x=>{const type=x.type==='quote'?'Quote':'Invoice',customer=x.customer?.name||'Customer not entered',job=x.job?.name||'Job not entered';return `<button class="qm-recent-row" data-qm-open-doc="${esc(x.id)}" type="button" aria-label="Open ${esc(type)} ${esc(x.number)} for ${esc(customer)}"><span class="qm-recent-icon">${paper}</span><span class="qm-recent-identity"><strong title="${esc(customer)}">${esc(customer)}</strong><span class="qm-recent-job" title="${esc(job)}">${esc(job)}</span><span class="qm-recent-number" title="${esc(x.number)}">${esc(type)} · ${esc(x.number)}</span></span><span class="qm-recent-value"><strong>${esc(money(x.totals?.totalCents||0))}</strong><span class="qm-recent-status"><span class="qm-pill ${x.status==='finalized'?'finalized':'draft'}">${x.status==='finalized'?'Finalized':'Draft'}</span>${x.isSample?'<span class="qm-recent-sample">Sample</span>':''}</span></span><span class="qm-recent-arrow">${arrow}</span></button>`;}).join('')}</div>`:'<div class="qm-recent-empty"><span class="qm-recent-icon">'+paper+'</span><div><strong>Your first document starts here.</strong><p>Create a quote or invoice above. Saved work will appear here.</p></div></div>'}</section><aside class="qm-workspace-links" aria-label="Workspace essentials"><button id="qmOverviewCatalog" class="qm-workspace-link" type="button"><span class="qm-link-icon">${icon('<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v9l9 5 9-5V8M12 13v9M7.5 5.5l9 5"/>')}</span><span><strong>Open parts &amp; services</strong><small>Part numbers, units &amp; pricing</small></span>${arrow}</button><button id="qmOverviewSetup" class="qm-workspace-link" type="button"><span class="qm-link-icon">${icon('<path d="M4 7h6m4 0h6M4 17h10m4 0h2"/><circle cx="12" cy="7" r="2"/><circle cx="16" cy="17" r="2"/>')}</span><span><strong>Business setup</strong><small>Business details &amp; backup</small></span>${arrow}</button></aside></div>${houseHull?`<div class="qm-studio-example"><div class="qm-example-symbol">${icon('<path d="m3 11 9-7 9 7M5 10v10h14V10M9 20v-7h6v7"/>')}</div><div class="qm-example-copy"><h3>Your HouseHull example</h3><p>Example quantities and prices are illustrative.</p></div><div class="qm-actions"><button id="qmSampleCatalog" type="button">Load example catalog</button><button id="qmExampleQuote" type="button">Create example quote ${arrow}</button></div></div>`:''}<p class="qm-studio-note">Each business keeps its own records. You decide when to share a PDF; supplier orders, payments and ledger entries are separate.</p>`;
}
